describe('Async Error with Retry Option', () => {
  beforeEach(() => {
    cy.visit('/async-operation');
  });

  it('should display retry button when async operation fails', () => {
    // Intercept the API call to simulate failure
    cy.intercept('GET', '/api/async-operation', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('asyncOperationFailed');

    // Attempt the async operation
    cy.get('[data-testid="start-async-btn"]').click();

    // Verify error state is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to complete operation');

    // Verify retry button is visible
    cy.get('[data-testid="retry-btn"]').should('be.visible');
    cy.get('[data-testid="retry-btn"]').should('contain', 'Retry');

    // Verify retry button is clickable
    cy.get('[data-testid="retry-btn"]').click();

    // Verify retry button is still visible after click
    cy.get('[data-testid="retry-btn"]').should('be.visible');

    // Verify error message is cleared after retry
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify success state is displayed after retry
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Operation completed successfully');
  });

  it('should not display retry button when operation succeeds on first attempt', () => {
    // Intercept the API call to simulate success
    cy.intercept('GET', '/api/async-operation', {
      statusCode: 200,
      body: { success: true, data: 'Operation completed' }
    }).as('asyncOperationSuccess');

    // Attempt the async operation
    cy.get('[data-testid="start-async-btn"]').click();

    // Verify success state is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Operation completed successfully');

    // Verify retry button is not visible
    cy.get('[data-testid="retry-btn"]').should('not.exist');

    // Verify error message is not displayed
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
